<template>
  <q-select
    outlined
    dense
    clearable
    use-input
    :disable="isReadOnly"
    v-model="selected_custom_model_label"
    :options="filtered_custom_model_label"
    @filter="filterlistEvent"
    emit-value
    map-options
    :label="$t('labels')"
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps" :disable="scope.opt.has_child">
        <q-item-section>
          <q-item-label
            v-if="!scope.opt.has_child"
            :class="
              'pl-20 ' +
              (sub_doc_type === scope.opt.value ? 'q-item--active' : '')
            "
            >{{ scope.opt.label }}</q-item-label
          >
          <q-item-label v-else>{{ scope.opt.label }}</q-item-label>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import {
  useCustomModelLabelsDropdownStore,
  useDocClassificationStore,
} from 'src/store/main';

export default defineComponent({
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  mixins: [],
  components: {},
  data() {
    return {};
  },
  watch: {
    custom_model_labels_loading: {
      handler: function (newVal, oldVal) {
        this.filtered_custom_model_label = this.custom_model_labels_list;
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    async initView() {
      await this.getModelLabels();
      this.prepareDropdown();
    },

    filterlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filtered_custom_model_label = this.custom_model_labels_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filtered_custom_model_label = this.custom_model_labels_list.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
  },

  setup() {
    const custom_model_labels_dropdown = useCustomModelLabelsDropdownStore();
    const { getModelLabels, prepareDropdown } = custom_model_labels_dropdown;
    const { custom_model_labels_list, custom_model_labels_loading } =
      storeToRefs(custom_model_labels_dropdown);

    const classification_store = useDocClassificationStore();
    const { selected_custom_model_label } = storeToRefs(classification_store);

    return {
      custom_model_labels_loading,
      custom_model_labels_list,
      selected_custom_model_label,
      filtered_custom_model_label: ref([] as any),
      getModelLabels,
      prepareDropdown,
    };
  },
});
</script>
